  padding: 14px 16px;
  border-radius: 999px;
  border: 1.5px solid var(--line);
  background: #fff;
  color: var(--ink);
  min-height: 48px;
}
.field input[type="email"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--ink);
}
.field input[aria-invalid="true"] { border-color: var(--sale); }
.field .error {
  color: var(--sale);
  font-size: 13px;
  display: none;
}
.field input[aria-invalid="true"] + .error,
.field .error[data-show="true"] { display: block; }
.required-mark { color: var(--sale); }
.form-status {
  margin-top: 8px;
  font-size: 14px;
  color: #166534;
  font-weight: 600;
  min-height: 20px;
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--ink);
  color: #d6d3d1;
  padding-top: 64px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 56px;
}
.site-footer h3 {
  color: #fff;
  font-size: 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin: 0 0 16px;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.site-footer a { color: #d6d3d1; text-decoration: none; }
.site-footer a:hover { color: #fff; text-decoration: underline; }
.footer-brand p { color: #a8a29e; max-width: 32ch; }
.social-row { display: flex; gap: 10px; margin-top: 16px; }
.social-row a {
  width: 40px; height: 40px;
  border: 1px solid #44403c;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.social-row a:hover { background: #fff; color: var(--ink); border-color: #fff; }
.footer-base {
  border-top: 1px solid #292524;
  padding: 22px 0;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: #a8a29e;
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.toast {
  background: var(--ink);
  color: #fff;
  padding: 12px 18px;
  border-radius: 12px;
  box-shadow: var(--shadow-md);
  font-size: 14px;
  pointer-events: auto;
  min-width: 220px;
  animation: toast-in .25s ease;
}
@keyframes toast-in {
  from { transform: translateY(8px); opacity: 0; }
  to { transform: none; opacity: 1; }
}

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-art { max-width: 520px; }
  .categories-grid { grid-template-columns: repeat(2, 1fr); }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .deals { grid-template-columns: 1fr; }
  .deals-art { max-width: 360px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.feature { grid-row: auto; grid-column: span 2; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
  .value-list { grid-template-columns: repeat(2, 1fr); }
  .value-list li:nth-child(3) { border-left: 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}

@media (max-width: 720px) {
  .menu-toggle {
    display: inline-flex;
    justify-self: end;
  }
  .header-inner {
    grid-template-columns: 1fr auto;
  }
  .primary-nav {
    grid-column: 1 / -1;
    display: none;
    border-top: 1px solid var(--line);
    padding-top: 12px;
    margin-top: 4px;
  }
  .primary-nav[data-open="true"] { display: block; }
  .primary-nav ul {
    flex-direction: column;
    gap: 6px;
  }
  .primary-nav a { display: block; padding: 10px 4px; }
  .header-actions { gap: 0; }
  .announcement-inner { gap: 16px; padding: 8px 0; font-size: 12px; }
}

@media (max-width: 540px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.feature { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr; gap: 28px; padding-bottom: 40px; }
  .value-list { grid-template-columns: 1fr; }
  .value-list li { border-left: 0; border-top: 1px solid var(--line); }
  .value-list li:first-child { border-top: 0; }
  .countdown li { padding: 10px 12px; min-width: 64px; }
  .countdown b { font-size: 22px; }
  .footer-base { justify-content: flex-start; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
  .btn:hover, .product-card:hover, .editorial-card:hover, .category-card:hover { transform: none; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn-primary,
  .btn-outline,
  .icon-btn,
  .product-card,
  .editorial-card,
  .category-card,
  .field input[type="email"] {
    border: 1px solid ButtonBorder;
  }
  .btn-primary { background: ButtonText; color: ButtonFace; }
  .icon-btn .badge { background: Highlight; color: HighlightText; forced-color-adjust: none; }
  /* Ensure focus outline renders */
  :focus-visible { outline: 3px solid Highlight; }
}
