/* ---------- Design tokens ---------- */
:root {
  --bg: #fafaf7;
  --surface: #ffffff;
  --surface-2: #f3f1ec;
  --ink: #15171a;
  --ink-2: #3a3f47;
  --muted: #5a6068;
  --line: #e3e0d8;
  --line-strong: #1a1c20;
  --accent: #c2410c;       /* deep terracotta */
  --accent-ink: #7a2808;
  --accent-soft: #fdebd9;
  --sale: #b91c1c;
  --focus: #1d4ed8;
  --shadow-sm: 0 1px 2px rgba(20,22,26,.06), 0 1px 1px rgba(20,22,26,.04);
  --shadow-md: 0 6px 24px rgba(20,22,26,.08);
  --radius-sm: 6px;
  --radius-md: 12px;
  --radius-lg: 20px;
  --maxw: 1240px;
  --space: clamp(16px, 2.4vw, 28px);
  --font-sans: "Inter", "Helvetica Neue", Arial, system-ui, sans-serif;
  --font-serif: "Fraunces", "Cormorant Garamond", Georgia, serif;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0;
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; }
button { font: inherit; cursor: pointer; }

/* ---------- Focus ---------- */
:focus { outline: none; }
:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

/* Skip link */
.skip-link {
  position: absolute;
  left: 12px;
  top: -100px;
  background: var(--ink);
  color: #fff;
  padding: 10px 16px;
  border-radius: 6px;
  z-index: 1000;
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus { top: 12px; }

/* ---------- Layout helpers ---------- */
.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--space);
}
.section { padding: clamp(48px, 7vw, 88px) 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  flex-wrap: wrap;
  margin-bottom: clamp(24px, 3vw, 40px);
}
.section-head h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.6vw, 44px);
  line-height: 1.1;
  margin: 0;
  letter-spacing: -0.01em;
}
.section-head p {
  margin: 8px 0 0;
  color: var(--muted);
  max-width: 52ch;
}
.section-head .head-link {
  font-weight: 600;
  text-decoration: none;
  border-bottom: 1px solid var(--ink);
  padding-bottom: 2px;
}
.section-head .head-link:hover { color: var(--accent-ink); border-color: var(--accent-ink); }

.eyebrow {
  display: inline-block;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent-ink);
  background: var(--accent-soft);
  padding: 6px 10px;
  border-radius: 999px;
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 12px 20px;
  border-radius: 999px;
  border: 1.5px solid transparent;
  text-decoration: none;
  font-weight: 600;
  transition: transform .15s ease, background .2s ease, color .2s ease, border-color .2s ease;
  min-height: 44px;
  white-space: nowrap;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary {
  background: var(--ink);
  color: #fff;
  border-color: var(--ink);
}
.btn-primary:hover { background: var(--accent-ink); border-color: var(--accent-ink); }
.btn-outline {
  background: transparent;
  color: var(--ink);
  border-color: var(--ink);
}
.btn-outline:hover { background: var(--ink); color: #fff; }
.btn-ghost {
  background: transparent;
  border-color: var(--line);
  color: var(--ink);
}
.btn-ghost:hover { border-color: var(--ink); }

/* ---------- Announcement ---------- */
.announcement {
  background: var(--ink);
  color: #fff;
  font-size: 13px;
  letter-spacing: 0.04em;
}
.announcement-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 24px;
  padding: 10px 0;
  text-align: center;
}
.announcement strong { font-weight: 600; }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(250, 250, 247, 0.92);
  backdrop-filter: saturate(140%) blur(8px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  padding: 14px 0;
}
.brand {
  font-family: var(--font-serif);
  font-size: 22px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
  color: var(--ink);
  justify-self: start;
}
.brand-mark {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}
.brand-mark .dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--accent);
}
.primary-nav ul {
  display: flex;
  gap: 28px;
  list-style: none;
  margin: 0;
  padding: 0;
}
.primary-nav a {
  text-decoration: none;
  color: var(--ink-2);
  font-weight: 500;
  padding: 8px 4px;
  position: relative;
}
.primary-nav a:hover { color: var(--ink); }
.primary-nav a[aria-current="page"]::after {
  content: "";
  position: absolute;
  left: 4px; right: 4px; bottom: 2px;
  height: 2px;
  background: var(--ink);
}
.header-actions {
  display: flex;
  gap: 4px;
  justify-self: end;
  align-items: center;
}
.icon-btn {
  width: 44px;
  height: 44px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  border: 1px solid transparent;
  border-radius: 999px;
  color: var(--ink);
  position: relative;
}
.icon-btn:hover { background: var(--surface-2); }
.icon-btn .badge {
  position: absolute;
  top: 6px;
  right: 6px;
  background: var(--accent);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.menu-toggle { display: none; }

/* ---------- Hero ---------- */
.hero {
  background: linear-gradient(180deg, #f6efe4 0%, #f1e7d6 100%);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
}
.hero-inner {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: clamp(24px, 4vw, 64px);
  align-items: center;
  padding: clamp(48px, 7vw, 96px) 0;
}
.hero-copy h1 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(40px, 6vw, 76px);
  line-height: 1.02;
  letter-spacing: -0.02em;
  margin: 18px 0 16px;
}
.hero-copy h1 em {
  font-style: italic;
  color: var(--accent-ink);
}
.hero-copy p {
  color: var(--ink-2);
  font-size: clamp(16px, 1.4vw, 18px);
  margin: 0 0 28px;
  max-width: 52ch;
}
.hero-cta { display: flex; flex-wrap: wrap; gap: 12px; }
.hero-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 24px 36px;
  margin-top: 36px;
  padding-top: 24px;
  border-top: 1px solid rgba(26,28,32,.12);
}
.hero-meta dt { font-family: var(--font-serif); font-size: 26px; font-weight: 500; }
.hero-meta dd { margin: 2px 0 0; color: var(--muted); font-size: 13px; letter-spacing: 0.06em; text-transform: uppercase; }
.hero-meta div { min-width: 0; }

.hero-art {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-md);
}
.hero-art .art-bg {
  position: absolute; inset: 0;
  background:
    radial-gradient(circle at 70% 30%, #fff 0%, transparent 45%),
    linear-gradient(135deg, #d97706 0%, #7c2d12 100%);
}
.hero-art .art-blob {
  position: absolute;
  border-radius: 50%;
  filter: blur(2px);
  mix-blend-mode: multiply;
}
.hero-art .blob-1 { width: 60%; height: 60%; top: -10%; left: -10%; background: #fde68a; opacity: .6; }
.hero-art .blob-2 { width: 50%; height: 50%; bottom: -15%; right: -10%; background: #fb923c; opacity: .55; }
.hero-art .blob-3 { width: 30%; height: 30%; top: 40%; left: 40%; background: #fef3c7; opacity: .8; }
.hero-art .product {
  position: absolute;
  inset: 12% 16% 14% 14%;
  background: linear-gradient(160deg, #fef3c7, #f59e0b);
  border-radius: 50%;
  box-shadow: inset -20px -30px 60px rgba(0,0,0,.15), 0 30px 80px rgba(0,0,0,.18);
}
.hero-art .label {
  position: absolute;
  top: 20px; left: 20px;
  background: rgba(255,255,255,.92);
  border-radius: 999px;
  padding: 8px 14px;
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.hero-art .price-tag {
  position: absolute;
  bottom: 20px;
  right: 20px;
  background: var(--ink);
  color: #fff;
  border-radius: 14px;
  padding: 14px 18px;
  text-align: right;
}
.hero-art .price-tag .name { font-size: 13px; opacity: .8; }
.hero-art .price-tag .price { font-family: var(--font-serif); font-size: 22px; }

/* ---------- Marquee strip ---------- */
.value-strip {
  border-bottom: 1px solid var(--line);
  background: var(--surface);
}
.value-list {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  list-style: none;
  margin: 0;
  padding: 0;
}
.value-list li {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px var(--space);
  border-left: 1px solid var(--line);
  color: var(--ink-2);
  font-size: 14px;
}
.value-list li:first-child { border-left: 0; }
.value-list svg { color: var(--accent-ink); flex-shrink: 0; }
.value-list strong { color: var(--ink); display: block; font-weight: 600; }

/* ---------- Categories ---------- */
.categories-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}
.category-card {
  position: relative;
  display: block;
  text-decoration: none;
  color: var(--ink);
  border-radius: var(--radius-md);
  overflow: hidden;
  aspect-ratio: 3 / 4;
  border: 1px solid var(--line);
  transition: transform .25s ease, box-shadow .25s ease;
}
.category-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.category-card .swatch {
  position: absolute; inset: 0;
}
.category-card .label-row {
  position: absolute;
  left: 14px; right: 14px; bottom: 14px;
  background: rgba(255,255,255,.95);
  border-radius: 10px;
  padding: 12px 14px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.category-card .label-row span:first-child { font-weight: 600; }
.category-card .label-row .arrow {
  width: 28px; height: 28px;
  border-radius: 50%;
  background: var(--ink); color: #fff;
  display: inline-flex; align-items: center; justify-content: center;
}

/* ---------- Featured products ---------- */
.products-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.product-card {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .25s ease, box-shadow .25s ease, border-color .2s ease;
}
.product-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); border-color: #d4d0c5; }
.product-media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--surface-2);
  overflow: hidden;
}
.product-media .art {
  position: absolute; inset: 0;
}
.product-tags {
  position: absolute;
  top: 12px; left: 12px;
  display: flex; flex-wrap: wrap; gap: 6px;
}
.tag {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 9px;
  border-radius: 999px;
  background: #fff;
  color: var(--ink);
  border: 1px solid var(--line);
}
.tag.tag-new { background: var(--ink); color: #fff; border-color: var(--ink); }
.tag.tag-sale { background: var(--sale); color: #fff; border-color: var(--sale); }
.tag.tag-eco { background: #166534; color: #fff; border-color: #166534; }

.wish-btn {
  position: absolute;
  top: 10px; right: 10px;
  width: 40px; height: 40px;
  border-radius: 50%;
  background: rgba(255,255,255,.92);
  border: 1px solid var(--line);
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--ink);
}
.wish-btn:hover { background: #fff; }
.wish-btn[aria-pressed="true"] { color: var(--sale); }

.product-body {
  padding: 16px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  flex: 1;
}
.product-cat {
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.product-title {
  margin: 0;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
}
.product-title a { text-decoration: none; }
.product-title a:hover { color: var(--accent-ink); }
.product-rating {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 13px;
}
.stars {
  --pct: 100%;
  display: inline-block;
  background: linear-gradient(90deg, #f59e0b var(--pct), #d6d2c8 var(--pct));
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-size: 14px;
  letter-spacing: 2px;
}
.product-price {
  margin-top: auto;
  padding-top: 8px;
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
.price-now { font-weight: 700; font-size: 17px; }
.price-was {
  color: var(--muted);
  text-decoration: line-through;
  font-size: 14px;
}
.price-save {
  margin-left: auto;
  background: var(--accent-soft);
  color: var(--accent-ink);
  padding: 3px 8px;
  border-radius: 6px;
  font-size: 12px;
  font-weight: 600;
}
.product-actions {
  display: flex;
  gap: 8px;
  padding: 0 16px 16px;
}
.product-actions .btn { flex: 1; padding: 10px 14px; }

/* ---------- Tabs ---------- */
.tabs {
  display: flex;
  gap: 6px;
  background: var(--surface-2);
  padding: 5px;
  border-radius: 999px;
  width: max-content;
  max-width: 100%;
  overflow-x: auto;
}
.tabs [role="tab"] {
  border: 0;
  background: transparent;
  padding: 8px 16px;
  border-radius: 999px;
  font-weight: 600;
  color: var(--ink-2);
  white-space: nowrap;
  min-height: 36px;
}
.tabs [role="tab"][aria-selected="true"] {
  background: var(--ink);
  color: #fff;
}
.tabs [role="tab"]:hover:not([aria-selected="true"]) { color: var(--ink); }

/* ---------- Deals banner ---------- */
.deals {
  background: linear-gradient(135deg, #1c1917 0%, #292524 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: clamp(28px, 4vw, 56px);
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
  position: relative;
  overflow: hidden;
}
.deals::before {
  content: "";
  position: absolute;
  width: 420px; height: 420px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(217,119,6,.4), transparent 65%);
  top: -100px; right: -120px;
  pointer-events: none;
}
.deals .eyebrow { background: rgba(255,255,255,.12); color: #fde68a; }
.deals h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(32px, 4vw, 52px);
  line-height: 1.05;
  margin: 14px 0 12px;
  letter-spacing: -0.01em;
}
.deals p { color: rgba(255,255,255,.78); margin: 0 0 24px; max-width: 50ch; }
.countdown {
  display: flex;
  gap: 12px;
  margin: 0 0 28px;
  padding: 0;
  list-style: none;
}
.countdown li {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 12px;
  padding: 12px 16px;
  text-align: center;
  min-width: 72px;
}
.countdown b {
  display: block;
  font-family: var(--font-serif);
  font-size: 28px;
  font-weight: 500;
}
.countdown span {
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255,255,255,.65);
}
.deals-cta { display: flex; flex-wrap: wrap; gap: 12px; }
.deals-cta .btn-primary { background: #fff; color: var(--ink); border-color: #fff; }
.deals-cta .btn-primary:hover { background: var(--accent); color: #fff; border-color: var(--accent); }
.deals-cta .btn-outline { color: #fff; border-color: rgba(255,255,255,.4); }
.deals-cta .btn-outline:hover { background: #fff; color: var(--ink); border-color: #fff; }

.deals-art {
  position: relative;
  aspect-ratio: 1;
  border-radius: var(--radius-md);
  background: linear-gradient(135deg, #f59e0b, #b45309);
  overflow: hidden;
}
.deals-art .ring {
  position: absolute;
  border: 2px solid rgba(255,255,255,.3);
  border-radius: 50%;
}
.deals-art .ring-1 { inset: 8%; }
.deals-art .ring-2 { inset: 22%; }
.deals-art .ring-3 { inset: 36%; }
.deals-art .badge {
  position: absolute;
  inset: 0;
  margin: auto;
  width: 140px; height: 140px;
  background: var(--ink);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  text-align: center;
  font-family: var(--font-serif);
}
.deals-art .badge b { font-size: 44px; line-height: 1; }
.deals-art .badge span { font-size: 11px; letter-spacing: 0.18em; text-transform: uppercase; margin-top: 6px; }

/* ---------- Editorial ---------- */
.editorial-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  gap: 20px;
}
.editorial-card {
  position: relative;
  display: flex;
  flex-direction: column;
  text-decoration: none;
  color: inherit;
  border-radius: var(--radius-md);
  overflow: hidden;
  background: var(--surface);
  border: 1px solid var(--line);
  min-height: 320px;
  transition: transform .25s ease, box-shadow .25s ease;
}
.editorial-card:hover { transform: translateY(-3px); box-shadow: var(--shadow-md); }
.editorial-card.feature { grid-row: span 2; min-height: 100%; }
.editorial-media {
  flex: 1;
  position: relative;
  min-height: 180px;
  overflow: hidden;
}
.editorial-card.feature .editorial-media { min-height: 320px; }
.editorial-body {
  padding: 20px 22px 22px;
  background: var(--surface);
}
.editorial-body .meta {
  display: flex;
  gap: 8px;
  align-items: center;
  font-size: 12px;
  color: var(--muted);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  margin-bottom: 8px;
}
.editorial-body .meta .dot-sep { width: 4px; height: 4px; border-radius: 50%; background: var(--muted); }
.editorial-body h3 {
  font-family: var(--font-serif);
  font-size: clamp(20px, 1.6vw, 26px);
  font-weight: 500;
  line-height: 1.2;
  margin: 0 0 8px;
}
.editorial-card.feature .editorial-body h3 {
  font-size: clamp(28px, 2.6vw, 38px);
}
.editorial-body p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

/* ---------- Newsletter ---------- */
.newsletter {
  background: var(--surface-2);
  border-top: 1px solid var(--line);
}
.newsletter-inner {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 48px;
  align-items: center;
  padding: clamp(48px, 6vw, 80px) 0;
}
.newsletter h2 {
  font-family: var(--font-serif);
  font-weight: 500;
  font-size: clamp(28px, 3.2vw, 40px);
  line-height: 1.1;
  margin: 12px 0 8px;
}
.newsletter p { color: var(--muted); margin: 0 0 8px; max-width: 46ch; }
.newsletter form {
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.field label { font-weight: 600; font-size: 14px; }
.field .help { color: var(--muted); font-size: 13px; }
.field-row {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.field input[type="email"] {
  flex: 1;
  min-width: 0;
  font: inherit;
  padding: 14px 16px;
  border-radius: 999px;
  border: 1.5px solid var(--line);
  background: #fff;
  color: var(--ink);
  min-height: 48px;
}
.field input[type="email"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--ink);
}
.field input[aria-invalid="true"] { border-color: var(--sale); }
.field .error {
  color: var(--sale);
  font-size: 13px;
  display: none;
}
.field input[aria-invalid="true"] + .error,
.field .error[data-show="true"] { display: block; }
.required-mark { color: var(--sale); }
.form-status {
  margin-top: 8px;
  font-size: 14px;
  color: #166534;
  font-weight: 600;
  min-height: 20px;
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--ink);
  color: #d6d3d1;
  padding-top: 64px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(4, 1fr);
  gap: 40px;
  padding-bottom: 56px;
}
.site-footer h3 {
  color: #fff;
  font-size: 14px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  margin: 0 0 16px;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 10px; }
.site-footer a { color: #d6d3d1; text-decoration: none; }
.site-footer a:hover { color: #fff; text-decoration: underline; }
.footer-brand p { color: #a8a29e; max-width: 32ch; }
.social-row { display: flex; gap: 10px; margin-top: 16px; }
.social-row a {
  width: 40px; height: 40px;
  border: 1px solid #44403c;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.social-row a:hover { background: #fff; color: var(--ink); border-color: #fff; }
.footer-base {
  border-top: 1px solid #292524;
  padding: 22px 0;
  display: flex;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px;
  font-size: 13px;
  color: #a8a29e;
}

/* ---------- Toast ---------- */
.toast-region {
  position: fixed;
  bottom: 24px;
  right: 24px;
  z-index: 200;
  display: flex;
  flex-direction: column;
  gap: 10px;
  pointer-events: none;
}
.toast {
  background: var(--ink);
  color: #fff;
  padding: 12px 18px;
  border-radius: 12px;
  box-shadow: var(--shadow-md);
  font-size: 14px;
  pointer-events: auto;
  min-width: 220px;
  animation: toast-in .25s ease;
}
@keyframes toast-in {
  from { transform: translateY(8px); opacity: 0; }
  to { transform: none; opacity: 1; }
}

/* ---------- Responsive ---------- */
@media (max-width: 980px) {
  .hero-inner { grid-template-columns: 1fr; }
  .hero-art { max-width: 520px; }
  .categories-grid { grid-template-columns: repeat(2, 1fr); }
  .products-grid { grid-template-columns: repeat(2, 1fr); }
  .deals { grid-template-columns: 1fr; }
  .deals-art { max-width: 360px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .editorial-card.feature { grid-row: auto; grid-column: span 2; }
  .newsletter-inner { grid-template-columns: 1fr; gap: 24px; }
  .value-list { grid-template-columns: repeat(2, 1fr); }
  .value-list li:nth-child(3) { border-left: 0; }
  .footer-grid { grid-template-columns: 1fr 1fr; gap: 32px; }
}

@media (max-width: 720px) {
  .menu-toggle {
    display: inline-flex;
    justify-self: end;
  }
  .header-inner {
    grid-template-columns: 1fr auto;
  }
  .primary-nav {
    grid-column: 1 / -1;
    display: none;
    border-top: 1px solid var(--line);
    padding-top: 12px;
    margin-top: 4px;
  }
  .primary-nav[data-open="true"] { display: block; }
  .primary-nav ul {
    flex-direction: column;
    gap: 6px;
  }
  .primary-nav a { display: block; padding: 10px 4px; }
  .header-actions { gap: 0; }
  .announcement-inner { gap: 16px; padding: 8px 0; font-size: 12px; }
}

@media (max-width: 540px) {
  .editorial-grid { grid-template-columns: 1fr; }
  .editorial-card.feature { grid-column: auto; }
  .footer-grid { grid-template-columns: 1fr; gap: 28px; padding-bottom: 40px; }
  .value-list { grid-template-columns: 1fr; }
  .value-list li { border-left: 0; border-top: 1px solid var(--line); }
  .value-list li:first-child { border-top: 0; }
  .countdown li { padding: 10px 12px; min-width: 64px; }
  .countdown b { font-size: 22px; }
  .footer-base { justify-content: flex-start; }
}

/* Reduced motion */
@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
  .btn:hover, .product-card:hover, .editorial-card:hover, .category-card:hover { transform: none; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn-primary,
  .btn-outline,
  .icon-btn,
  .product-card,
  .editorial-card,
  .category-card,
  .field input[type="email"] {
    border: 1px solid ButtonBorder;
  }
  .btn-primary { background: ButtonText; color: ButtonFace; }
  .icon-btn .badge { background: Highlight; color: HighlightText; forced-color-adjust: none; }
  /* Ensure focus outline renders */
  :focus-visible { outline: 3px solid Highlight; }
}

