  background: var(--ink);
  color: #fff;
  padding: 10px 16px;
  border-radius: 6px;
  z-index: 1000;
  text-decoration: none;
  font-weight: 600;
}
.skip-link:focus { top: 12px; }

/* ---------- Layout helpers ---------- */
.container {
  width: 100%;
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 var(--space);
}
.section { padding: clamp(48px, 7vw, 88px) 0; }
.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
