      ))
    ),
    h("div", { className: "container footer-base" },
      h("span", null, "© 2026 Maren Studio · Copenhagen"),
      h("span", null,
        h("a", { href: "#privacy" }, "Privacy"), " · ",
        h("a", { href: "#terms" }, "Terms"), " · ",
        h("a", { href: "#accessibility" }, "Accessibility")
      )
    )
  );
};

const ToastRegion = ({ toasts }) =>
  h("div", { className: "toast-region", role: "status", "aria-live": "polite", "aria-atomic": "true" },
    toasts.map(t => h("div", { key: t.id, className: "toast" }, t.text))
  );

/* ---------- App ---------- */
const App = () => {
  const [cart, setCart] = useState([]);
  const [wishlist, setWishlist] = useState(new Set());
  const [toasts, setToasts] = useState([]);

  const pushToast = useCallback((text) => {
    const id = Math.random().toString(36).slice(2);
    setToasts(t => [...t, { id, text }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 2600);
  }, []);

  const addToCart = useCallback((p) => {
    setCart(c => [...c, p.id]);
    pushToast(`Added “${p.name}” to bag`);
  }, [pushToast]);

  const toggleWish = useCallback((p) => {
    setWishlist(s => {
      const next = new Set(s);
      if (next.has(p.id)) {
        next.delete(p.id);
        pushToast(`Removed “${p.name}” from wishlist`);
      } else {
        next.add(p.id);
        pushToast(`Saved “${p.name}” to wishlist`);
      }
      return next;
    });
  }, [pushToast]);

  return h(Fragment, null,
    h(Announcement),
    h(Header, { cartCount: cart.length, wishCount: wishlist.size, onCartOpen: () => pushToast(`${cart.length} item${cart.length === 1 ? "" : "s"} in your bag`) }),
    h("main", { id: "main" },
      h(Hero),
      h(ValueStrip),
      h(Categories),
      h(FeaturedProducts, { wishlist, onWish: toggleWish, onAdd: addToCart }),
      h(Deals),
      h(Editorial),
      h(Newsletter, { onSubscribed: () => pushToast("Subscribed — welcome.") })
    ),
    h(Footer),
    h(ToastRegion, { toasts })
  );
};

ReactDOM.createRoot(document.getElementById("root")).render(h(App));
