const ProductCard = ({ product, wished, onWish, onAdd }) => {
  const tagInfo = (t) => ({
    new: { cls: "tag tag-new", label: "New" },
    sale: { cls: "tag tag-sale", label: "Sale" },
    eco: { cls: "tag tag-eco", label: "Eco" },
  })[t];
  const save = product.was ? Math.round(((product.was - product.price) / product.was) * 100) : 0;

  return h("article", { className: "product-card", "aria-labelledby": `pt-${product.id}` },
    h("div", { className: "product-media" },
      h("div", { className: "art", style: { background: product.gradient }, "aria-hidden": "true" }),
      product.tags.length > 0 && h("div", { className: "product-tags" },
        product.tags.map(t => {
          const info = tagInfo(t);
          return info ? h("span", { key: t, className: info.cls }, info.label) : null;
        })
      ),
      h("button", {
        type: "button",
        className: "wish-btn",
        "aria-pressed": wished,
        "aria-label": `${wished ? "Remove" : "Add"} ${product.name} ${wished ? "from" : "to"} wishlist`,
        onClick: () => onWish(product),
      }, h(Icon, { name: "heart", size: 18 }))
    ),
    h("div", { className: "product-body" },
      h("span", { className: "product-cat" }, product.category),
      h("h3", { className: "product-title", id: `pt-${product.id}` },
        h("a", { href: `#${product.id}` }, product.name)
      ),
      h("div", { className: "product-rating" },
        h(Stars, { value: product.rating }),
        h("span", null, `${product.rating.toFixed(1)} (${product.reviews})`)
      ),
      h("div", { className: "product-price" },
        h("span", { className: "price-now" }, `$${product.price}`),
        product.was && h("span", { className: "price-was", "aria-label": `Was $${product.was}` }, `$${product.was}`),
        save > 0 && h("span", { className: "price-save" }, `Save ${save}%`)
      )
    ),
    h("div", { className: "product-actions" },
      h("button", {
        type: "button",
        className: "btn btn-primary",
        onClick: () => onAdd(product),
        "aria-label": `Add ${product.name} to bag`,
