const FeaturedProducts = ({ wishlist, onWish, onAdd }) => {
  const [tab, setTab] = useState("best");
  const tabRefs = useRef({});

  const filtered = useMemo(() => {
    if (tab === "new") return PRODUCTS.filter(p => p.tags.includes("new"));
    if (tab === "sale") return PRODUCTS.filter(p => p.tags.includes("sale"));
    return PRODUCTS;
  }, [tab]);

  const onTabKey = (e, idx) => {
    if (e.key !== "ArrowRight" && e.key !== "ArrowLeft" && e.key !== "Home" && e.key !== "End") return;
    e.preventDefault();
    let next = idx;
    if (e.key === "ArrowRight") next = (idx + 1) % TABS.length;
    if (e.key === "ArrowLeft") next = (idx - 1 + TABS.length) % TABS.length;
    if (e.key === "Home") next = 0;
    if (e.key === "End") next = TABS.length - 1;
    const id = TABS[next].id;
    setTab(id);
    requestAnimationFrame(() => tabRefs.current[id]?.focus());
  };

  return h("section", { className: "section", id: "featured", "aria-labelledby": "featured-title" },
    h("div", { className: "container" },
      h("div", { className: "section-head" },
        h("div", null,
          h("span", { className: "eyebrow" }, "Featured"),
          h("h2", { id: "featured-title" }, "Pieces we love right now."),
          h("p", null, "A weekly edit from our buying team — small batches, often limited, always considered.")
        ),
        h("div", { className: "tabs", role: "tablist", "aria-label": "Featured product filters" },
          TABS.map((t, idx) => h("button", {
            key: t.id,
            type: "button",
            role: "tab",
            id: `tab-${t.id}`,
            "aria-selected": tab === t.id,
            "aria-controls": `panel-${t.id}`,
            tabIndex: tab === t.id ? 0 : -1,
            ref: el => { tabRefs.current[t.id] = el; },
            onClick: () => setTab(t.id),
            onKeyDown: (e) => onTabKey(e, idx),
          }, t.label))
        )
      ),
      h("div", {
        className: "products-grid",
        role: "tabpanel",
        id: `panel-${tab}`,
        "aria-labelledby": `tab-${tab}`,
      },
        filtered.length > 0
          ? filtered.map(p => h(ProductCard, {
              key: p.id, product: p,
              wished: wishlist.has(p.id),
              onWish, onAdd,
            }))
          : h("p", { style: { color: "var(--muted)" } }, "No products in this view yet — check back soon.")
      )
    )
  );
};

const Countdown = () => {
  const target = useMemo(() => Date.now() + (1000 * 60 * 60 * 47) + (1000 * 60 * 32), []);
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(t);
  }, []);
  const diff = Math.max(0, target - now);
  const days = Math.floor(diff / 86400000);
  const hours = Math.floor((diff / 3600000) % 24);
  const mins = Math.floor((diff / 60000) % 60);
  const secs = Math.floor((diff / 1000) % 60);
  const pad = (n) => String(n).padStart(2, "0");
  const items = [
    { v: pad(days), l: "Days" },
    { v: pad(hours), l: "Hours" },
    { v: pad(mins), l: "Min" },
    { v: pad(secs), l: "Sec" },
  ];
  return h("ul", {
    className: "countdown",
    "aria-label": `Sale ends in ${days} days, ${hours} hours, ${mins} minutes`,
  },
    items.map(it => h("li", { key: it.l, "aria-hidden": "true" },
      h("b", null, it.v),
      h("span", null, it.l)
    ))
  );
};

