const Newsletter = ({ onSubscribed }) => {
  const [email, setEmail] = useState("");
  const [touched, setTouched] = useState(false);
  const [status, setStatus] = useState("");
  const inputRef = useRef(null);

  const isValidEmail = (v) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim());
  const showError = touched && !isValidEmail(email);

  const onSubmit = (e) => {
    e.preventDefault();
    if (!isValidEmail(email)) {
      setTouched(true);
      setStatus("");
      inputRef.current?.focus();
      return;
    }
    setStatus(`Thanks — we've added ${email} to the list.`);
    setEmail("");
    setTouched(false);
    onSubscribed?.();
  };

  return h("section", { className: "newsletter", "aria-labelledby": "news-title" },
    h("div", { className: "container newsletter-inner" },
      h("div", null,
        h("span", { className: "eyebrow" }, "Stay close"),
        h("h2", { id: "news-title" }, "A letter, twice a month."),
        h("p", null, "New arrivals, member-only previews, and the occasional studio recipe. No noise — promise.")
      ),
      h("form", { onSubmit, noValidate: true, "aria-describedby": "news-status" },
        h("div", { className: "field" },
          h("label", { htmlFor: "news-email" },
            "Email address ", h("span", { className: "required-mark", "aria-hidden": "true" }, "*")
          ),
          h("div", { className: "field-row" },
            h("input", {
              id: "news-email",
              type: "email",
              autoComplete: "email",
              required: true,
              "aria-required": "true",
              "aria-invalid": showError ? "true" : "false",
              "aria-describedby": "news-help news-error",
              value: email,
              ref: inputRef,
              onChange: (e) => setEmail(e.target.value),
              onBlur: () => setTouched(true),
              placeholder: "you@studio.com",
            }),
            h("button", { type: "submit", className: "btn btn-primary" }, "Subscribe")
          ),
          h("span", { id: "news-help", className: "help" }, "Required. We'll never share your address."),
          h("span", { id: "news-error", className: "error", "data-show": showError ? "true" : "false", role: showError ? "alert" : undefined },
            "Please enter a valid email address."
          )
        ),
        h("div", { id: "news-status", className: "form-status", role: "status", "aria-live": "polite" }, status)
      )
    )
  );
};

